     public async Task<string> GetPosts(
         [Description("Filter posts by this user ID (omit for all posts)")] int? userId = null,
         CancellationToken cancellationToken = default)
     {
         var url = userId.HasValue
             ? $"https://jsonplaceholder.typicode.com/posts?userId={userId}"
             : "https://jsonplaceholder.typicode.com/posts";

         logger.LogInformation("Fetching posts from {Url}", url);
         var json = await httpClient.GetStringAsync(url, cancellationToken);

         using var doc = JsonDocument.Parse(json);
         var count = doc.RootElement.GetArrayLength();
         return $"Found {count} posts:\n{JsonSerializer.Serialize(doc, JsonOptions)}";
     }

     [McpServerTool, Description("Get a single post by its ID.")]
     public async Task<string> GetPost(
         [Description("The numeric ID of the post to retrieve")] int postId,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Fetching post {PostId}", postId);
         var response = await httpClient.GetAsync(
             $"https://jsonplaceholder.typicode.com/posts/{postId}", cancellationToken);

         if (!response.IsSuccessStatusCode)
             return $"Error: received HTTP {(int)response.StatusCode} for post {postId}.";

         var json = await response.Content.ReadAsStringAsync(cancellationToken);
         return JsonSerializer.Serialize(JsonDocument.Parse(json), JsonOptions);
     }

     [McpServerTool(Destructive = false, ReadOnly = true),
      Description("Get all comments on a specific post.")]
     public async Task<string> GetComments(
         [Description("The post ID whose comments to retrieve")] int postId,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Fetching comments for post {PostId}", postId);
         var json = await httpClient.GetStringAsync(
             $"https://jsonplaceholder.typicode.com/posts/{postId}/comments", cancellationToken);
         return json;
     }

     [McpServerTool(Destructive = false),
      Description("Create a new post (simulated — JSONPlaceholder returns the created object but does not persist it).")]
     public async Task<string> CreatePost(
         [Description("Title of the new post")] string title,
         [Description("Body content of the new post")] string body,
         [Description("User ID of the post author")] int userId,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Creating post for user {UserId}", userId);

         var payload = JsonSerializer.Serialize(new { title, body, userId });
         var content = new StringContent(payload, Encoding.UTF8, "application/json");

         var response = await httpClient.PostAsync(
             "https://jsonplaceholder.typicode.com/posts", content, cancellationToken);

         var result = await response.Content.ReadAsStringAsync(cancellationToken);
         return $"HTTP {(int)response.StatusCode}:\n{JsonSerializer.Serialize(JsonDocument.Parse(result), JsonOptions)}";
     }
 }
